import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useLocation, useParams, useSearchParams } from 'react-router-dom';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import {
  Input,
  LinPageHeader,
  SearchInput,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { notificationService } from '../../services/notification/notificationService';
import { opsListPermissions } from '../../services/notification/permissions';
import type { NotificationDto } from '../../services/notification/responseModel';
import {
  CHANNEL_LOOKUP,
  CHANNEL_LOOKUP_CONFIG,
  DIRECTION_LOOKUP,
  DIRECTION_LOOKUP_CONFIG,
  ORG_UNIT_LOOKUP,
  ORG_UNIT_LOOKUP_CONFIG,
  PRIORITY_LOOKUP,
  PRIORITY_LOOKUP_CONFIG,
  RECIPIENT_LOOKUP,
  RECIPIENT_LOOKUP_CONFIG,
  STATUS_LOOKUP,
  STATUS_LOOKUP_CONFIG,
  TYPE_LOOKUP,
  TYPE_LOOKUP_CONFIG,
  lookupLabel,
} from '../../services/notification/lookups';
import {
  EMPTY_FORM,
  genOpsCode,
  loadRows,
  type OpsRow,
} from '../../demo/opsStore';
import { buildRmmsDetailToolbar, rmmsFormActionButton } from '../buildRmmsGenericToolbar';
import styles from './NotificationFormPage.module.css';

export type OpsFormMode = 'create' | 'edit' | 'view' | 'copy';

type FormState = Omit<OpsRow, 'id'>;

const REQUIRED: (keyof FormState)[] = ['title', 'body', 'recipient'];
const TEST_ID = 'rmms-ops-form';
const PAGE_ID = 'ops-form';

const MODE_TITLE: Record<OpsFormMode, string> = {
  create: 'Tạo chỉ đạo',
  edit: 'Sửa chỉ đạo',
  view: 'Xem chỉ đạo',
  copy: 'Sao chép chỉ đạo',
};

function toLocalInput(iso: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function fromLocalInput(local: string): string {
  if (!local) return new Date().toISOString();
  const d = new Date(local);
  return Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

function fromDto(dto: NotificationDto, asCopy: boolean): FormState {
  return {
    code: asCopy ? genOpsCode(loadRows()) : dto.code,
    title: asCopy ? `${dto.title} (sao chép)` : dto.title,
    body: dto.body,
    recipient: dto.recipient,
    priority: dto.priority ?? 'cao',
    type: dto.type ?? 'tuan-tra',
    status: asCopy ? 'nhap' : dto.status,
    channel: dto.channel ?? 'inbox',
    sender: dto.sender ?? 'Hạt trưởng A',
    linkRef: dto.linkRef ?? '',
    reply: asCopy ? '' : dto.reply ?? '',
    sentAt: dto.sentAt ?? new Date().toISOString(),
    isUnread: asCopy ? true : Boolean(dto.isUnread),
    documentNumber: dto.documentNumber ?? '',
    direction: dto.direction ?? 'di',
    summary: dto.summary ?? '',
    orgUnitCode: dto.orgUnitCode ?? 'cc2',
    orgUnitName: dto.orgUnitName ?? lookupLabel(ORG_UNIT_LOOKUP, dto.orgUnitCode ?? 'cc2'),
    updatedAt: dto.updatedAt ?? '',
    isActive: dto.isActive !== false,
  };
}

function formatSentAt(iso?: string): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('vi-VN');
}

const CREATE_SLUGS = new Set(['new', 'tao-moi']);

const NotificationFormPage: React.FC = () => {
  const { id } = useParams();
  const { pathname } = useLocation();
  const [searchParams] = useSearchParams();
  const navigate = useInAppNavigate();
  const dispatch = useDispatch();
  const perms = opsListPermissions();
  const copyFrom = searchParams.get('copyFrom');
  const modeParam = searchParams.get('mode');

  const mode: OpsFormMode = useMemo(() => {
    const isCreatePath =
      pathname.endsWith('/tao-moi') || !id || CREATE_SLUGS.has(id);
    if (isCreatePath) return copyFrom ? 'copy' : 'create';
    if (modeParam === 'edit') return 'edit';
    if (modeParam === 'copy') return 'copy';
    return 'view';
  }, [id, copyFrom, modeParam, pathname]);

  const isView = mode === 'view';
  const [form, setForm] = useState<FormState>({ ...EMPTY_FORM });
  const [currentId, setCurrentId] = useState<string | null>(null);
  const [invalid, setInvalid] = useState<Set<string>>(new Set());
  const [showBanner, setShowBanner] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      setLoading(true);
      setInvalid(new Set());
      setShowBanner(false);
      setDirty(false);
      try {
        if (mode === 'create') {
          setCurrentId(null);
          setForm({
            ...EMPTY_FORM,
            code: '(tự sinh)',
            sentAt: new Date().toISOString(),
            updatedAt: '',
          });
          return;
        }
        const sourceId = mode === 'copy' ? copyFrom ?? id : id;
        if (!sourceId) {
          navigate('/chi-dao');
          return;
        }
        const dto = await notificationService.getById(sourceId);
        if (cancelled) return;
        if (mode === 'view' && dto.isUnread) {
          void notificationService.markRead(dto.id);
        }
        setCurrentId(mode === 'copy' ? null : dto.id);
        setForm(fromDto(dto, mode === 'copy'));
      } catch (err) {
        if (!cancelled) {
          dispatchAppToast(dispatch, {
            message:
              err instanceof Error
                ? err.message
                : 'Không tải được chỉ đạo. Quay lại danh sách.',
            type: 'error',
          });
          navigate('/chi-dao');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void boot();
    return () => {
      cancelled = true;
    };
  }, [mode, id, copyFrom, navigate, dispatch]);

  const updateField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    if (isView) return;
    setDirty(true);
    setForm((prev) => ({ ...prev, [key]: value }));
    setInvalid((prev) => {
      const next = new Set(prev);
      next.delete(String(key));
      return next;
    });
  };

  const goList = () => {
    if (!isView && dirty) {
      const ok = window.confirm('Bạn có thay đổi chưa lưu. Thoát mà không lưu?');
      if (!ok) return;
    }
    navigate('/chi-dao');
  };

  const handleSave = async (nextStatus?: string) => {
    if (isView) return;
    if (mode === 'edit' && !perms.canUpdate) return;
    if ((mode === 'create' || mode === 'copy') && !perms.canCreate) return;
    const statusToSave = nextStatus ?? form.status;
    const snapshot = { ...form, status: statusToSave };
    if (nextStatus) setForm(snapshot);
    const bad = new Set<string>();
    REQUIRED.forEach((key) => {
      const val = snapshot[key];
      if (val === '' || val == null || (typeof val === 'string' && !val.trim())) {
        bad.add(key);
      }
    });
    setInvalid(bad);
    setShowBanner(bad.size > 0);
    if (bad.size > 0) return;
    setSaving(true);
    try {
      const payload = {
        title: snapshot.title.trim(),
        body: snapshot.body.trim(),
        recipient: snapshot.recipient,
        priority: snapshot.priority,
        type: snapshot.type,
        status: statusToSave,
        channel: snapshot.channel,
        sender: snapshot.sender.trim() || undefined,
        linkRef: snapshot.linkRef.trim() || undefined,
        reply: snapshot.reply.trim() || undefined,
        sentAt: snapshot.sentAt,
        documentNumber: snapshot.documentNumber.trim() || undefined,
        direction: snapshot.direction || undefined,
        summary: snapshot.summary.trim() || undefined,
        orgUnitCode: snapshot.orgUnitCode || undefined,
        orgUnitName: snapshot.orgUnitName || undefined,
      };
      if (mode === 'edit' && currentId) {
        await notificationService.update(currentId, payload);
      } else {
        await notificationService.create(payload);
      }
      setDirty(false);
      navigate('/chi-dao');
    } finally {
      setSaving(false);
    }
  };

  const clearBody = () => {
    if (isView) return;
    updateField('body', '');
    updateField('reply', '');
  };

  const fieldClass = (key: string) =>
    [styles.field, invalid.has(key) ? styles.fieldInvalid : ''].filter(Boolean).join(' ');

  const toolbar = buildRmmsDetailToolbar({
    testIdPrefix: TEST_ID,
    onBack: goList,
    right: (
      <>
        {isView && currentId && perms.canUpdate
          ? rmmsFormActionButton({
              testId: 'ops-btn-to-edit',
              label: 'Sửa',
              icon: 'fas fa-pen',
              onClick: () => navigate(`/chi-dao/${encodeURIComponent(currentId)}?mode=edit`),
            })
          : null}
        {isView && currentId && perms.canCreate
          ? rmmsFormActionButton({
              testId: 'ops-btn-to-copy',
              label: 'Sao chép',
              icon: 'fas fa-copy',
              onClick: () =>
                navigate(`/chi-dao/tao-moi?copyFrom=${encodeURIComponent(currentId)}`),
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: 'ops-btn-cancel',
              label: 'Hủy',
              icon: 'fas fa-times',
              onClick: goList,
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: 'ops-btn-clear',
              label: 'Xóa nội dung',
              icon: 'fas fa-eraser',
              onClick: clearBody,
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: 'ops-btn-assign',
              label: 'Giao việc P2',
              icon: 'fas fa-share',
              onClick: () => window.alert('Giao việc — DEFER P2 (GAP-F-OPS-01).'),
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: 'ops-btn-draft',
              label: 'Lưu nháp',
              icon: 'fas fa-file',
              onClick: () => void handleSave('nhap'),
              loading: saving,
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: 'ops-btn-send',
              label: 'Gửi chỉ đạo',
              icon: 'fas fa-paper-plane',
              variant: 'primary',
              onClick: () => void handleSave('da-gui'),
              loading: saving,
            })
          : null}
      </>
    ),
  });

  const viewBody = (
    <dl className={styles.viewGrid} data-form-cols="5" data-testid={`${TEST_ID}-view`}>
      <div>
        <dt>Mã chỉ đạo</dt>
        <dd>{form.code || '—'}</dd>
      </div>
      <div>
        <dt>Số công văn</dt>
        <dd>{form.documentNumber || '—'}</dd>
      </div>
      <div>
        <dt>Chiều</dt>
        <dd>{lookupLabel(DIRECTION_LOOKUP, form.direction)}</dd>
      </div>
      <div>
        <dt>Đơn vị</dt>
        <dd>{form.orgUnitName || lookupLabel(ORG_UNIT_LOOKUP, form.orgUnitCode) || '—'}</dd>
      </div>
      <div>
        <dt>Trạng thái</dt>
        <dd>{lookupLabel(STATUS_LOOKUP, form.status)}</dd>
      </div>
      <div className={styles.spanFull}>
        <dt>Trích yếu</dt>
        <dd>{form.summary || '—'}</dd>
      </div>
      <div>
        <dt>Người gửi</dt>
        <dd>{form.sender || '—'}</dd>
      </div>
      <div>
        <dt>Thời gian gửi</dt>
        <dd>{formatSentAt(form.sentAt)}</dd>
      </div>
      <div>
        <dt>Người nhận / đội</dt>
        <dd>{lookupLabel(RECIPIENT_LOOKUP, form.recipient)}</dd>
      </div>
      <div>
        <dt>Độ ưu tiên</dt>
        <dd>{lookupLabel(PRIORITY_LOOKUP, form.priority)}</dd>
      </div>
      <div>
        <dt>Loại chỉ đạo</dt>
        <dd>{lookupLabel(TYPE_LOOKUP, form.type)}</dd>
      </div>
      <div className={styles.spanFull}>
        <dt>Tiêu đề</dt>
        <dd>{form.title || '—'}</dd>
      </div>
      <div className={styles.spanFull}>
        <dt>Nội dung</dt>
        <dd>{form.body || '—'}</dd>
      </div>
      <div>
        <dt>Kênh gửi</dt>
        <dd>{lookupLabel(CHANNEL_LOOKUP, form.channel)}</dd>
      </div>
      <div className={styles.span2}>
        <dt>Liên kết nguồn</dt>
        <dd>{form.linkRef || '—'}</dd>
      </div>
      <div className={styles.spanFull}>
        <dt>Phản hồi thread (P2)</dt>
        <dd>{form.reply || '—'}</dd>
      </div>
    </dl>
  );

  const editBody = (
    <div className={styles.z2} data-testid="ops-form-z2">
      <section>
        <h3 className={styles.sectionTitle}>Thông tin chỉ đạo</h3>
        <div className={styles.fields} data-form-cols="5">
          <div className={fieldClass('code')}>
            <Input
              label="Mã chỉ đạo"
              value={form.code}
              disabled
              fullWidth
              data-testid="ops-field-code"
            />
          </div>
          <div className={styles.field}>
            <Input
              label="Số công văn"
              value={form.documentNumber}
              onChange={(e) => updateField('documentNumber', e.target.value)}
              fullWidth
              data-testid="ops-field-documentNumber"
            />
          </div>
          <div className={styles.field} data-testid="ops-field-direction">
            <SearchInput
              label="Chiều"
              config={DIRECTION_LOOKUP_CONFIG}
              value={form.direction}
              primaryDisplay={lookupLabel(DIRECTION_LOOKUP, form.direction)}
              showSecondaryInput={false}
              onChange={(item) => updateField('direction', item.value)}
              onClear={() => updateField('direction', '')}
            />
          </div>
          <div className={styles.field} data-testid="ops-field-orgUnit">
            <SearchInput
              label="Đơn vị"
              config={ORG_UNIT_LOOKUP_CONFIG}
              value={form.orgUnitCode}
              primaryDisplay={
                form.orgUnitName || lookupLabel(ORG_UNIT_LOOKUP, form.orgUnitCode)
              }
              showSecondaryInput={false}
              onChange={(item) => {
                setDirty(true);
                setForm((prev) => ({
                  ...prev,
                  orgUnitCode: item.value,
                  orgUnitName: lookupLabel(ORG_UNIT_LOOKUP, item.value),
                }));
              }}
              onClear={() => {
                setDirty(true);
                setForm((prev) => ({ ...prev, orgUnitCode: '', orgUnitName: '' }));
              }}
            />
          </div>
          <div className={fieldClass('status')} data-testid="ops-field-status">
            <SearchInput
              label="Trạng thái"
              config={STATUS_LOOKUP_CONFIG}
              value={form.status}
              primaryDisplay={lookupLabel(STATUS_LOOKUP, form.status)}
              showSecondaryInput={false}
              onChange={(item) => updateField('status', item.value)}
              onClear={() => updateField('status', '')}
            />
          </div>
          <div className={`${styles.field} ${styles.spanFull}`}>
            <label className={styles.label}>
              Trích yếu
              <textarea
                className={styles.textarea}
                value={form.summary}
                onChange={(e) => updateField('summary', e.target.value)}
                placeholder="Trích yếu công văn…"
                data-testid="ops-field-summary"
              />
            </label>
          </div>
          <div className={styles.field}>
            <Input
              label="Người gửi"
              value={form.sender}
              onChange={(e) => updateField('sender', e.target.value)}
              fullWidth
              data-testid="ops-field-sender"
            />
          </div>
          <div className={fieldClass('sentAt')}>
            <Input
              label="Thời gian gửi"
              type="datetime-local"
              value={toLocalInput(form.sentAt)}
              onChange={(e) => updateField('sentAt', fromLocalInput(e.target.value))}
              fullWidth
              data-testid="ops-field-sentAt"
            />
          </div>
          <div className={fieldClass('recipient')} data-testid="ops-field-recipient">
            <SearchInput
              label="Người nhận / đội"
              required
              config={RECIPIENT_LOOKUP_CONFIG}
              value={form.recipient}
              primaryDisplay={lookupLabel(RECIPIENT_LOOKUP, form.recipient)}
              showSecondaryInput={false}
              onChange={(item) => updateField('recipient', item.value)}
              onClear={() => updateField('recipient', '')}
              error={invalid.has('recipient') ? 'Bắt buộc' : undefined}
            />
          </div>
          <div className={styles.field} data-testid="ops-field-priority">
            <SearchInput
              label="Độ ưu tiên"
              config={PRIORITY_LOOKUP_CONFIG}
              value={form.priority}
              primaryDisplay={lookupLabel(PRIORITY_LOOKUP, form.priority)}
              showSecondaryInput={false}
              onChange={(item) => updateField('priority', item.value)}
              onClear={() => updateField('priority', '')}
            />
          </div>
          <div className={styles.field} data-testid="ops-field-type">
            <SearchInput
              label="Loại chỉ đạo"
              config={TYPE_LOOKUP_CONFIG}
              value={form.type}
              primaryDisplay={lookupLabel(TYPE_LOOKUP, form.type)}
              showSecondaryInput={false}
              onChange={(item) => updateField('type', item.value)}
              onClear={() => updateField('type', '')}
            />
          </div>
          <div className={`${fieldClass('title')} ${styles.spanFull}`}>
            <Input
              label="Tiêu đề"
              required
              value={form.title}
              onChange={(e) => updateField('title', e.target.value)}
              fullWidth
              error={invalid.has('title') ? 'Bắt buộc' : undefined}
              data-testid="ops-field-title"
            />
          </div>
          <div className={`${fieldClass('body')} ${styles.spanFull}`}>
            <label className={styles.label}>
              Nội dung <span className={styles.req}>*</span>
              <textarea
                className={styles.textarea}
                value={form.body}
                onChange={(e) => updateField('body', e.target.value)}
                placeholder="Nội dung chỉ đạo…"
                data-testid="ops-field-body"
              />
            </label>
          </div>
          <div className={styles.field} data-testid="ops-field-channel">
            <SearchInput
              label="Kênh gửi"
              config={CHANNEL_LOOKUP_CONFIG}
              value={form.channel}
              primaryDisplay={lookupLabel(CHANNEL_LOOKUP, form.channel)}
              showSecondaryInput={false}
              onChange={(item) => updateField('channel', item.value)}
              onClear={() => updateField('channel', '')}
            />
          </div>
          <div className={`${styles.field} ${styles.span2}`}>
            <Input
              label="Liên kết nguồn (INC/WO/PAT)"
              value={form.linkRef}
              onChange={(e) => updateField('linkRef', e.target.value)}
              fullWidth
              data-testid="ops-field-linkRef"
            />
          </div>
          <div className={`${styles.field} ${styles.spanFull}`}>
            <label className={styles.label}>
              Phản hồi thread (P2)
              <textarea
                className={styles.textarea}
                value={form.reply}
                onChange={(e) => updateField('reply', e.target.value)}
                placeholder="Phản hồi…"
                data-testid="ops-field-reply"
              />
            </label>
          </div>
        </div>
      </section>
    </div>
  );

  useShellPageTitle(MODE_TITLE[mode]);
  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <LinPageHeader
        pageId={PAGE_ID}
        testIdPrefix={TEST_ID}
        title={MODE_TITLE[mode]}
        titleIconClass="fas fa-bullhorn"
        hint="Chỉ đạo điều hành · inbox Notification"
      />
      {toolbar}
      {loading ? (
        <div className={styles.loading} data-testid="ops-form-loading">
          Đang tải…
        </div>
      ) : (
        <>
          {showBanner ? (
            <div className={styles.banner} data-testid={`${TEST_ID}-banner`}>
              Vui lòng nhập đủ các trường bắt buộc (tiêu đề, nội dung, người nhận).
            </div>
          ) : null}
          {isView ? viewBody : editBody}
        </>
      )}
    </div>
  );
};

export default NotificationFormPage;
